pan style="color: #9876AA">1234</span><span style="color: #007700">, </span><span style="color: #9876AA">5678</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">((string) </span><span style="color: #9876AA">\$timestamp</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">string(11)&nbsp;"[1234:5678]"</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-timestamp.tostring-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/#timestamps" class="link external">»&nbsp;BSON Types: Timestamps</a></li>  </ul> </div></div>
